cat > src/params.rs <<'EOF'
//! Typed access to the members of a command object.
//!
//! A `null` member counts as absent. Callers check required members with
//! [`Params::require`] before reading any value, because a missing parameter
//! outranks a badly typed one.

use crate::error::{Error, ErrorCode, Result};
use serde_json::{Map, Value};
use std::ops::RangeInclusive;

#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    pub fn members(&self) -> &'a Map<String, Value> {
        self.0
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn has(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| !self.has(name)) {
            Some(name) => Err(Error::new(
                ErrorCode::MissingParameter,
                format!("{name} is required"),
            )),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| {
                v.as_str()
                    .ok_or_else(|| Error::invalid_value(format!("{name} must be a string")))
            })
            .transpose()
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| {
                v.as_bool()
                    .ok_or_else(|| Error::invalid_value(format!("{name} must be a boolean")))
            })
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|v| {
                v.as_object()
                    .ok_or_else(|| Error::invalid_value(format!("{name} must be an object")))
            })
            .transpose()
    }

    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                v.as_i64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        Error::invalid_value(format!(
                            "{name} must be an integer from {} to {}",
                            range.start(),
                            range.end()
                        ))
                    })
            })
            .transpose()
    }

    /// A 1 to 128 character identifier from `A-Z a-z 0-9 _ -`.
    pub fn identifier(&self, name: &str) -> Result<Option<&'a str>> {
        let Some(value) = self.string(name)? else {
            return Ok(None);
        };
        let valid = (1..=128).contains(&value.len()) && value.bytes().all(is_name_byte);
        if valid {
            Ok(Some(value))
        } else {
            Err(Error::invalid_value(format!(
                "{name} must be 1 to 128 characters from A-Z a-z 0-9 _ -"
            )))
        }
    }
}

pub fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}
