cat > src/queue.rs <<'EOF'
//! Queue state: attributes, messages and the bookkeeping that keeps
//! receive, delete and retention cheap.

use crate::error::{Error, ErrorCode, Result};
use crate::params::{Params, is_name_byte};
use std::collections::{BTreeMap, HashMap};

pub const MAX_MESSAGES: usize = 100_000;
pub const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

/// The attributes a request names; absent ones are left alone.
#[derive(Debug, Default)]
pub struct AttributePatch {
    visibility_timeout: Option<u32>,
    delay_seconds: Option<u32>,
    retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u32>,
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

impl AttributePatch {
    pub fn parse(params: Params<'_>) -> Result<Self> {
        let Some(members) = params.object("Attributes")? else {
            return Ok(Self::default());
        };
        if let Some(unknown) = members.keys().find(|k| !ATTRIBUTE_NAMES.contains(&k.as_str())) {
            return Err(Error::invalid_value(format!("unknown attribute {unknown}")));
        }
        let attrs = Params::new(members);
        Ok(Self {
            visibility_timeout: attrs.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: attrs.integer("DelaySeconds", 0..=900)?,
            retention_seconds: attrs.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: attrs.boolean("Fifo")?,
            content_based_deduplication: attrs.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: attrs.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: attrs.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// The two dead-letter attributes only make sense together.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (None, None) => Ok(None),
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue: queue.clone(),
                max_receive_count,
            })),
            _ => Err(Error::invalid_value(
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }
}

impl Attributes {
    pub fn apply(&mut self, patch: &AttributePatch, dead_letter: Option<DeadLetter>) {
        self.visibility_timeout = patch.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = patch.delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = patch.retention_seconds.unwrap_or(self.retention_seconds);
        self.fifo = patch.fifo.unwrap_or(self.fifo);
        self.content_based_deduplication = patch
            .content_based_deduplication
            .unwrap_or(self.content_based_deduplication);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }
}

pub fn validate_queue_name(name: &str) -> Result<()> {
    let stem = name.strip_suffix(".fifo").map_or((name, 80), |s| (s, 75));
    let valid = (1..=stem.1).contains(&stem.0.len()) && stem.0.bytes().all(is_name_byte);
    if valid {
        Ok(())
    } else {
        Err(Error::new(
            ErrorCode::QueueNameInvalid,
            "queue names are 1 to 80 characters from A-Z a-z 0-9 _ - with an optional .fifo suffix",
        ))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group_id: Option<String>,
    pub sequence: Option<u64>,
    pub delay_until: u64,
    pub in_flight_until: u64,
    pub handle: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        if now < self.delay_until {
            State::Delayed
        } else if now < self.in_flight_until {
            State::InFlight
        } else {
            State::Visible
        }
    }
}

/// A remembered deduplication id and the message it produced.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: u64,
}

#[derive(Debug)]
pub struct Queue {
    pub attrs: Attributes,
    /// Keyed by arrival number, so iteration is arrival order.
    pub messages: BTreeMap<u64, Message>,
    /// Latest receipt handle number to the arrival number of its message.
    pub handles: HashMap<u64, u64>,
    pub dedup: HashMap<String, Accepted>,
    next_arrival: u64,
    next_sequence: u64,
    /// Lower bound of `sent_at` over `messages`, so retention sweeps are
    /// skipped until something can actually have expired.
    oldest_sent_at: u64,
}

impl Queue {
    pub fn new(attrs: Attributes) -> Self {
        Self {
            attrs,
            messages: BTreeMap::new(),
            handles: HashMap::new(),
            dedup: HashMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            oldest_sent_at: u64::MAX,
        }
    }

    /// Adds `message` at the end; returns its sequence number on a FIFO queue.
    pub fn append(&mut self, mut message: Message) -> Option<u64> {
        message.sequence = self.attrs.fifo.then(|| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            sequence
        });
        let sequence = message.sequence;
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
        sequence
    }

    pub fn remove(&mut self, arrival: u64) -> Option<Message> {
        let message = self.messages.remove(&arrival)?;
        if let Some(handle) = message.handle {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    /// Drops every message, keeping sequence numbers and deduplication.
    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
        self.oldest_sent_at = u64::MAX;
    }

    /// Applies retention for time `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attrs.retention_seconds);
        if now < self.oldest_sent_at.saturating_add(retention) {
            return;
        }
        let expired: Vec<u64> = self
            .messages
            .iter()
            .filter(|(_, m)| now >= m.sent_at + retention)
            .map(|(&arrival, _)| arrival)
            .collect();
        for arrival in expired {
            self.remove(arrival);
        }
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }
}
