        message.sequence = self.attrs.fifo.then(|| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            sequence
        });
        let sequence = message.sequence;
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
        sequence
    }

    pub fn remove(&mut self, arrival: u64) -> Option<Message> {
        let message = self.messages.remove(&arrival)?;
        if let Some(handle) = message.handle {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    /// Drops every message, keeping sequence numbers and deduplication.
    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
        self.oldest_sent_at = u64::MAX;
    }

    /// Applies retention for time `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attrs.retention_seconds);
        if now < self.oldest_sent_at.saturating_add(retention) {
            return;
        }
        let expired: Vec<u64> = self
            .messages
            .iter()
            .filter(|(_, m)| now >= m.sent_at + retention)
            .map(|(&arrival, _)| arrival)
            .collect();
        for arrival in expired {
            self.remove(arrival);
        }
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }
}
