//! Command dispatch and the queue-level commands.

use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;
use crate::queue::{AttributePatch, Attributes, Queue, State, validate_queue_name};
use serde_json::{Map, Value, json};
use std::collections::HashMap;

const MAX_QUEUES: usize = 1000;

#[derive(Default)]
pub struct Engine {
    pub(crate) queues: HashMap<String, Queue>,
    pub(crate) now: u64,
    pub(crate) last_message_id: u64,
    pub(crate) last_handle: u64,
}

impl Engine {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line and returns the one-line JSON response.
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.run(line) {
            Ok(mut result) => {
                result.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(result)
            }
            Err(e) => json!({
                "ok": false,
                "error": {"code": e.code.as_str(), "message": e.message},
            }),
        };
        response.to_string()
    }

    fn run(&mut self, line: &[u8]) -> Result<Map<String, Value>> {
        let invalid = |what: &str| Error::new(ErrorCode::InvalidRequest, what.to_owned());
        let text = std::str::from_utf8(line).map_err(|_| invalid("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str(text) else {
            return Err(invalid("line is not a JSON object"));
        };
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(invalid("Command must be a string"));
        };
        let params = Params::new(&members);
        let result = match command.as_str() {
            "CreateQueue" => self.create_queue(params),
            "SetQueueAttributes" => self.set_queue_attributes(params),
            "GetQueueAttributes" => self.get_queue_attributes(params),
            "ListQueues" => self.list_queues(params),
            "DeleteQueue" => self.delete_queue(params),
            "PurgeQueue" => self.purge_queue(params),
            "Tick" => self.tick(params),
            "SendMessage" => self.send_message(params),
            "ReceiveMessage" => self.receive_message(params),
            "DeleteMessage" => self.delete_message(params),
            "ChangeMessageVisibility" => self.change_message_visibility(params),
            _ => return Err(invalid("unknown command")),
        }?;
        Ok(match result {
            Value::Object(map) => map,
            _ => Map::new(),
        })
    }

    /// Finds a queue and applies retention to it for the current time.
    pub(crate) fn queue_mut<'a>(
        queues: &'a mut HashMap<String, Queue>,
        now: u64,
        name: &str,
    ) -> Result<&'a mut Queue> {
        let queue = queues.get_mut(name).ok_or_else(|| {
            Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {name:?}"))
        })?;
        queue.expire(now);
        Ok(queue)
    }

    fn create_queue(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = params
            .string("QueueName")?
            .ok_or_else(|| Error::invalid_value("QueueName must be a string"))?;
        validate_queue_name(name)?;
        let patch = AttributePatch::parse(params)?;
        let fifo = patch.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "a queue name ends in .fifo exactly when Fifo is true",
            ));
        }
        if patch.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid_value(
                "ContentBasedDeduplication needs a FIFO queue",
            ));
        }
        let dead_letter = patch.dead_letter()?;
        let mut attrs = Attributes::default();
        attrs.apply(&patch, dead_letter.clone());

        if let Some(existing) = self.queues.get(name) {
            return if existing.attrs == attrs {
                Ok(json!({}))
            } else {
                Err(Error::new(
                    ErrorCode::QueueAlreadyExists,
                    format!("queue {name:?} exists with different attributes"),
                ))
            };
        }
        if let Some(dead_letter) = &dead_letter {
            self.check_dead_letter_target(&dead_letter.queue, fifo)?;
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(ErrorCode::LimitExceeded, "1000 queues already exist"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attrs));
        Ok(json!({}))
    }

    fn check_dead_letter_target(&self, target: &str, fifo: bool) -> Result<()> {
        let target = self.queues.get(target).ok_or_else(|| {
            Error::new(ErrorCode::QueueDoesNotExist, format!("no dead-letter queue {target:?}"))
        })?;
        if target.attrs.fifo == fifo {
            Ok(())
        } else {
            Err(Error::invalid_value(
                "a dead-letter queue must have the same Fifo setting",
            ))
        }
    }

    fn set_queue_attributes(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName", "Attributes"])?;
        let name = required_string(params, "QueueName")?;
        let patch = AttributePatch::parse(params)?;
        let queue = Self::queue_mut(&mut self.queues, self.now, name)?;
        if patch.fifo.is_some() {
            return Err(Error::new(
                ErrorCode::UnsupportedOperation,
                "the type of a queue cannot change",
            ));
        }
        if patch.content_based_deduplication == Some(true) && !queue.attrs.fifo {
            return Err(Error::invalid_value(
                "ContentBasedDeduplication needs a FIFO queue",
            ));
        }
        let fifo = queue.attrs.fifo;
        let dead_letter = patch.dead_letter()?;
        if let Some(dead_letter) = &dead_letter {
            if !self.queues.contains_key(&dead_letter.queue) {
                return Err(Error::new(
                    ErrorCode::QueueDoesNotExist,
                    format!("no dead-letter queue {:?}", dead_letter.queue),
                ));
            }
            if dead_letter.queue == name {
                return Err(Error::invalid_value("a queue cannot be its own dead-letter queue"));
            }
            self.check_dead_letter_target(&dead_letter.queue, fifo)?;
        }
        if let Some(queue) = self.queues.get_mut(name) {
            queue.attrs.apply(&patch, dead_letter);
        }
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_string(params, "QueueName")?;
        let now = self.now;
        let queue = Self::queue_mut(&mut self.queues, now, name)?;
        let a = &queue.attrs;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(dead_letter) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(dead_letter.queue);
            attributes["MaxReceiveCount"] = json!(dead_letter.max_receive_count);
        }
        let mut counts = [0u64; 3];
        for message in queue.messages.values() {
            counts[match message.state(now) {
                State::Visible => 0,
                State::InFlight => 1,
                State::Delayed => 2,
            }] += 1;
        }
        Ok(json!({
            "Attributes": attributes,
            "Counts": {"Visible": counts[0], "InFlight": counts[1], "Delayed": counts[2]},
        }))
    }

    fn list_queues(&mut self, params: Params<'_>) -> Result<Value> {
        let prefix = params.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        names.sort();
        Ok(json!({"QueueNames": names}))
    }

    fn delete_queue(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_string(params, "QueueName")?;
        Self::queue_mut(&mut self.queues, self.now, name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attrs.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attrs.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_string(params, "QueueName")?;
        Self::queue_mut(&mut self.queues, self.now, name)?.purge();
        Ok(json!({}))
    }

    fn tick(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["Seconds"])?;
        let seconds = params.integer("Seconds", 0..=1_209_600)?.unwrap_or(0);
        self.now += u64::from(seconds);
        Ok(json!({"Now": self.now}))
    }
}

pub(crate) fn required_string<'a>(params: Params<'a>, name: &str) -> Result<&'a str> {
    params
        .string(name)?
        .ok_or_else(|| Error::new(ErrorCode::MissingParameter, format!("{name} is required")))
}
