//! Message commands: send, receive, delete and change visibility.

use crate::engine::{Engine, required_string};
use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;
use crate::queue::{Accepted, DEDUP_WINDOW, MAX_MESSAGES, Message, State};
use serde_json::{Value, json};
use std::collections::HashSet;

impl Engine {
    pub(crate) fn send_message(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName", "Body"])?;
        let name = required_string(params, "QueueName")?;
        let body = required_string(params, "Body")?;
        if !(1..=1024).contains(&body.len()) {
            return Err(Error::invalid_value("Body must be 1 to 1024 bytes"));
        }
        let delay = params.integer("DelaySeconds", 0..=900)?;
        let group = params.identifier("GroupId")?;
        let dedup_id = params.identifier("DeduplicationId")?;

        let now = self.now;
        let queue = Self::queue_mut(&mut self.queues, now, name)?;
        let fifo = queue.attrs.fifo;
        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(
                ErrorCode::UnsupportedOperation,
                "this parameter is not supported by this type of queue",
            ));
        }
        let missing = |name: &str| Error::new(ErrorCode::MissingParameter, format!("{name} is required"));
        let mut dedup_key = None;
        if fifo {
            if group.is_none() {
                return Err(missing("GroupId"));
            }
            if dedup_id.is_none() && !queue.attrs.content_based_deduplication {
                return Err(missing("DeduplicationId"));
            }
            let key = dedup_id.unwrap_or(body);
            if let Some(seen) = queue.dedup.get(key).filter(|a| now - a.at < DEDUP_WINDOW) {
                return Ok(json!({"MessageId": format!("m-{}", seen.message_id), "SequenceNumber": seen.sequence}));
            }
            dedup_key = Some(key);
        }
        if queue.messages.len() >= MAX_MESSAGES {
            return Err(Error::new(ErrorCode::LimitExceeded, "queue holds 100000 messages"));
        }

        self.last_message_id += 1;
        let message_id = self.last_message_id;
        let delay = delay.unwrap_or(queue.attrs.delay_seconds);
        let sequence = queue.append(Message {
            id: message_id,
            body: body.to_owned(),
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id: group.map(str::to_owned),
            sequence: None,
            delay_until: now + u64::from(delay),
            in_flight_until: 0,
            handle: None,
        });
        let mut result = json!({"MessageId": format!("m-{message_id}")});
        if let (Some(key), Some(sequence)) = (dedup_key, sequence) {
            queue.dedup.insert(key.to_owned(), Accepted { at: now, message_id, sequence });
            result["SequenceNumber"] = json!(sequence);
        }
        Ok(result)
    }

    pub(crate) fn receive_message(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_string(params, "QueueName")?;
        let max = params.integer("MaxMessages", 1..=10)?.unwrap_or(1) as usize;
        let timeout = params.integer("VisibilityTimeout", 0..=43_200)?;

        let now = self.now;
        let queue = Self::queue_mut(&mut self.queues, now, name)?;
        let timeout = u64::from(timeout.unwrap_or(queue.attrs.visibility_timeout));
        let dead_letter = queue.attrs.dead_letter.clone();
        let fifo = queue.attrs.fifo;

        let mut delivered = Vec::new();
        let mut to_move = Vec::new();
        let mut groups_seen: HashSet<String> = HashSet::new();
        for (&arrival, message) in queue.messages.iter_mut() {
            if delivered.len() >= max {
                break;
            }
            // An earlier message of the group, in any state, blocks this one.
            if let Some(group) = &message.group_id {
                if groups_seen.contains(group) {
                    continue;
                }
                groups_seen.insert(group.clone());
            }
            if message.state(now) != State::Visible {
                continue;
            }
            if dead_letter.as_ref().is_some_and(|d| message.receive_count >= d.max_receive_count) {
                // Leaving the queue, so it no longer blocks its group.
                if let Some(group) = &message.group_id {
                    groups_seen.remove(group);
                }
                to_move.push(arrival);
                continue;
            }
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            self.last_handle += 1;
            if let Some(old) = message.handle.replace(self.last_handle) {
                queue.handles.remove(&old);
            }
            queue.handles.insert(self.last_handle, arrival);
            message.in_flight_until = now + timeout;

            let mut entry = json!({
                "MessageId": format!("m-{}", message.id),
                "ReceiptHandle": format!("r-{}", self.last_handle),
                "Body": message.body,
                "ReceiveCount": message.receive_count,
                "SentAt": message.sent_at,
                "FirstReceivedAt": message.first_received_at,
            });
            if fifo {
                entry["GroupId"] = json!(message.group_id);
                entry["SequenceNumber"] = json!(message.sequence);
            }
            delivered.push(entry);
        }

        let moved: Vec<Message> = to_move.into_iter().filter_map(|a| queue.remove(a)).collect();
        if let (Some(dead_letter), false) = (dead_letter, moved.is_empty()) {
            let target = Self::queue_mut(&mut self.queues, now, &dead_letter.queue)?;
            for mut message in moved {
                message.receive_count = 0;
                message.first_received_at = None;
                message.delay_until = 0;
                message.in_flight_until = 0;
                target.append(message);
            }
        }
        Ok(json!({"Messages": delivered}))
    }

    pub(crate) fn delete_message(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName", "ReceiptHandle"])?;
        let name = required_string(params, "QueueName")?;
        let handle = required_string(params, "ReceiptHandle")?;
        let now = self.now;
        let issued = self.last_handle;
        let queue = Self::queue_mut(&mut self.queues, now, name)?;
        let arrival = in_flight_arrival(queue, handle, issued, now)?;
        queue.remove(arrival);
        Ok(json!({}))
    }

    pub(crate) fn change_message_visibility(&mut self, params: Params<'_>) -> Result<Value> {
        params.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let name = required_string(params, "QueueName")?;
        let handle = required_string(params, "ReceiptHandle")?;
        let timeout = params.integer("VisibilityTimeout", 0..=43_200)?.unwrap_or(0);
        let now = self.now;
        let issued = self.last_handle;
        let queue = Self::queue_mut(&mut self.queues, now, name)?;
        let arrival = in_flight_arrival(queue, handle, issued, now)?;
        if let Some(message) = queue.messages.get_mut(&arrival) {
            message.in_flight_until = now + u64::from(timeout);
        }
        Ok(json!({}))
    }
}

/// Resolves a receipt handle to its message, which must be in flight.
fn in_flight_arrival(queue: &crate::queue::Queue, handle: &str, issued: u64, now: u64) -> Result<u64> {
    let invalid = || Error::new(ErrorCode::ReceiptHandleInvalid, "receipt handle was never issued");
    // Exact spelling only: no sign, no leading zeros, no whitespace.
    let digits = handle.strip_prefix("r-").ok_or_else(invalid)?;
    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err(invalid());
    }
    let number: u64 = digits.parse().map_err(|_| invalid())?;
    if !(1..=issued).contains(&number) {
        return Err(invalid());
    }
    let expired = || Error::new(ErrorCode::ReceiptHandleExpired, "receipt handle is no longer usable");
    let arrival = *queue.handles.get(&number).ok_or_else(expired)?;
    match queue.messages.get(&arrival) {
        Some(m) if m.state(now) == State::InFlight => Ok(arrival),
        _ => Err(expired()),
    }
}
