use miniq::Engine;
use serde_json::{Value, json};

fn run(engine: &mut Engine, command: Value) -> Value {
    serde_json::from_str(&engine.handle_line(command.to_string().as_bytes())).unwrap()
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().unwrap()
}

fn queue(engine: &mut Engine, name: &str, attributes: Value) {
    let r = run(engine, json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
    assert_eq!(r, json!({"ok": true}));
}

fn tick(engine: &mut Engine, seconds: u32) {
    run(engine, json!({"Command": "Tick", "Seconds": seconds}));
}

fn send(engine: &mut Engine, name: &str, body: &str) -> Value {
    run(engine, json!({"Command": "SendMessage", "QueueName": name, "Body": body}))
}

fn receive(engine: &mut Engine, name: &str) -> Value {
    run(engine, json!({"Command": "ReceiveMessage", "QueueName": name}))
}

#[test]
fn malformed_lines_are_invalid_requests() {
    let mut e = Engine::new();
    for line in [&b""[..], b"[]", b"{\"Command\": 1}", b"{\"Command\": \"Nope\"}", b"\xff", b"{} x"] {
        let r: Value = serde_json::from_str(&e.handle_line(line)).unwrap();
        assert_eq!(code(&r), "InvalidRequest");
    }
}

#[test]
fn missing_beats_invalid_and_integers_are_strict() {
    let mut e = Engine::new();
    let r = run(&mut e, json!({"Command": "SendMessage", "QueueName": 5}));
    assert_eq!(code(&r), "MissingParameter");
    let r: Value = serde_json::from_str(&e.handle_line(br#"{"Command":"Tick","Seconds":3.0}"#)).unwrap();
    assert_eq!(code(&r), "InvalidParameterValue");
}

#[test]
fn create_queue_is_idempotent_only_for_equal_attributes() {
    let mut e = Engine::new();
    queue(&mut e, "a", json!({"VisibilityTimeout": 5}));
    queue(&mut e, "a", json!({"VisibilityTimeout": 5, "DelaySeconds": null}));
    let r = run(&mut e, json!({"Command": "CreateQueue", "QueueName": "a"}));
    assert_eq!(code(&r), "QueueAlreadyExists");
    let r = run(&mut e, json!({"Command": "CreateQueue", "QueueName": "b.fifo"}));
    assert_eq!(code(&r), "QueueNameInvalid");
    let r = run(&mut e, json!({"Command": "CreateQueue", "QueueName": "c", "Attributes": {"Bogus": 1}}));
    assert_eq!(code(&r), "InvalidParameterValue");
}

#[test]
fn list_queues_sorts_by_bytes() {
    let mut e = Engine::new();
    for name in ["b", "B", "_", "a-1", "a.fifo"] {
        let fifo = name.ends_with(".fifo");
        queue(&mut e, name, json!({"Fifo": fifo}));
    }
    let r = run(&mut e, json!({"Command": "ListQueues"}));
    assert_eq!(r["QueueNames"], json!(["B", "_", "a-1", "a.fifo", "b"]));
    let r = run(&mut e, json!({"Command": "ListQueues", "Prefix": "a"}));
    assert_eq!(r["QueueNames"], json!(["a-1", "a.fifo"]));
}

#[test]
fn receive_hides_message_until_visibility_timeout_ends() {
    let mut e = Engine::new();
    queue(&mut e, "q", json!({"VisibilityTimeout": 10}));
    assert_eq!(send(&mut e, "q", "hi")["MessageId"], "m-1");
    let first = receive(&mut e, "q");
    assert_eq!(first["Messages"][0]["ReceiptHandle"], "r-1");
    assert_eq!(first["Messages"][0]["ReceiveCount"], 1);
    assert_eq!(first["Messages"][0]["FirstReceivedAt"], 0);
    assert_eq!(receive(&mut e, "q")["Messages"], json!([]));
    tick(&mut e, 10);
    let again = receive(&mut e, "q");
    assert_eq!(again["Messages"][0]["ReceiptHandle"], "r-2");
    assert_eq!(again["Messages"][0]["ReceiveCount"], 2);
    let stale = run(&mut e, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}));
    assert_eq!(code(&stale), "ReceiptHandleExpired");
    let bad = run(&mut e, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-02"}));
    assert_eq!(code(&bad), "ReceiptHandleInvalid");
    let ok = run(&mut e, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-2"}));
    assert_eq!(ok, json!({"ok": true}));
}

#[test]
fn delay_and_retention_drive_counts() {
    let mut e = Engine::new();
    queue(&mut e, "q", json!({"DelaySeconds": 5}));
    send(&mut e, "q", "x");
    let counts = |e: &mut Engine| run(e, json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts(&mut e), json!({"Visible": 0, "InFlight": 0, "Delayed": 1}));
    tick(&mut e, 5);
    assert_eq!(counts(&mut e), json!({"Visible": 1, "InFlight": 0, "Delayed": 0}));
    let r = run(&mut e, json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"RetentionSeconds": 60}}));
    assert_eq!(r, json!({"ok": true}));
    tick(&mut e, 55);
    assert_eq!(counts(&mut e), json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

