fn fifo_blocks_group_and_deduplicates() {
    let mut e = Engine::new();
    queue(&mut e, "q.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    let send = |e: &mut Engine, body: &str, group: &str| {
