    assert_eq!((dup["MessageId"].clone(), dup["SequenceNumber"].clone()), (json!("m-1"), json!(1)));
    let got = run(&mut e, json!({"Command": "ReceiveMessage", "QueueName": "q.fifo", "MaxMessages": 10}));
    let bodies: Vec<_> = got["Messages"].as_array().unwrap().iter().map(|m| m["Body"].clone()).collect();
    assert_eq!(bodies, [json!("a"), json!("c")]);
    tick(&mut e, 300);
    assert_eq!(send(&mut e, "a", "g1")["MessageId"], "m-4");
    let r = run(&mut e, json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "z"}));
    assert_eq!(code(&r), "MissingParameter");
}

#[test]
fn messages_move_to_dead_letter_queue_after_max_receives() {
    let mut e = Engine::new();
    queue(&mut e, "dead", json!({}));
    queue(&mut e, "q", json!({"VisibilityTimeout": 0, "DeadLetterQueue": "dead", "MaxReceiveCount": 2}));
    send(&mut e, "q", "x");
    assert_eq!(receive(&mut e, "q")["Messages"].as_array().unwrap().len(), 1);
    assert_eq!(receive(&mut e, "q")["Messages"].as_array().unwrap().len(), 1);
    assert_eq!(receive(&mut e, "q")["Messages"], json!([]));
    let moved = receive(&mut e, "dead");
    assert_eq!(moved["Messages"][0]["MessageId"], "m-1");
    assert_eq!(moved["Messages"][0]["ReceiveCount"], 1);
    let r = run(&mut e, json!({"Command": "DeleteQueue", "QueueName": "dead"}));
    assert_eq!(r, json!({"ok": true}));
    let attrs = run(&mut e, json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("DeadLetterQueue").is_none());
}

