fn change_visibility_zero_releases_message() {
    let mut e = Engine::new();
    queue(&mut e, "q", json!({}));
    send(&mut e, "q", "x");
    receive(&mut e, "q");
    let r = run(&mut e, json!({"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": "r-1", "VisibilityTimeout": 0}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(receive(&mut e, "q")["Messages"][0]["ReceiveCount"], 2);
}

#[test]
fn queue_holds_at_most_100000_messages_quickly() {
    let mut e = Engine::new();
    queue(&mut e, "q", json!({}));
    let line = br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#;
    for _ in 0..100_000 {
        e.handle_line(line);
    }
    let r: Value = serde_json::from_str(&e.handle_line(line)).unwrap();
    assert_eq!(code(&r), "LimitExceeded");
}
