    assert_eq!(receive(&mut e, "q")["Messages"][0]["ReceiveCount"], 2);
}

#[test]
fn queue_holds_at_most_100000_messages_quickly() {
    let mut e = Engine::new();
    queue(&mut e, "q", json!({}));
    let line = br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#;
    for _ in 0..100_000 {
        e.handle_line(line);
    }
    let r: Value = serde_json::from_str(&e.handle_line(line)).unwrap();
    assert_eq!(code(&r), "LimitExceeded");
}
